/* AdventureSpark adventure lists. One object per line so changes diff cleanly.
   cat: outdoor | creative | food | wellness | urban | social
   mins: 30, 60, 90, 240 (half day), 600 (full day), 2880 (weekend)   spend: 0 free, 1 budget, 2 moderate, 3 splurge
   effort: 1 gentle, 2 steady, 3 big effort   who: s solo, p pair, g group   where: in | out | any   light: day | night | any
   reach: 0 from your door, 1 short trip, 2 anywhere   season: "" any, "w" warm months, "c" cold months   ages: baby | toddler | child | teenager */
window.ADVENTURES={
adults:[
  {"id":"1","title":"Sunrise Hilltop Hike","desc":"Wake before dawn and hike to the nearest hilltop to watch the sunrise. Bring a thermos of coffee and a blanket.","cat":"outdoor","mins":240,"spend":0,"effort":2,"who":"sp","where":"out","light":"any","reach":1,"kit":["Hiking boots or sturdy shoes","Thermos with hot drink","Blanket or sit mat","Head torch","Layered clothing","Phone/camera for photos"],"tip":"Check the sunrise time the night before. Arrive 20 mins early to find a good spot. Dress warmer than you think — it's always colder at altitude before dawn.","season":""},
  {"id":"2","title":"Sketch a Stranger's Dog","desc":"Head to a park with a sketchbook. Ask someone if you can draw their dog. Gift them the sketch.","cat":"creative","mins":60,"spend":0,"effort":1,"who":"s","where":"out","light":"day","reach":0,"kit":["Sketchbook or loose paper","Pencils or pens","Eraser","Something to sit on"],"tip":"Dogs in parks are usually relaxed after a walk — the best time to sketch. Start with quick gesture drawings. Most owners love it — just ask politely first.","season":""},
  {"id":"3","title":"Night Market Food Crawl","desc":"Visit a local night market or food street. Try at least 5 things you've never eaten before.","cat":"food","mins":240,"spend":1,"effort":1,"who":"pg","where":"out","light":"night","reach":1,"kit":["Cash (many stalls don't take card)","Napkins/wet wipes","Reusable bag for leftovers","Comfy shoes","Empty stomach"],"tip":"Go with friends and share portions so you can try more. Ask stall holders what's popular. Arrive early for the best selection.","season":""},
  {"id":"4","title":"Wild Swimming Expedition","desc":"Find a safe wild swimming spot — a lake, river, or sea cove. Pack towels, snacks, and courage.","cat":"outdoor","mins":600,"spend":0,"effort":2,"who":"sp","where":"out","light":"day","reach":2,"kit":["Swimsuit","Towel (microfibre is great)","Dry bag for valuables","Warm layers for after","Water shoes","Snacks and water","First aid kit"],"tip":"Check water quality and currents before you go. Never swim alone. A hot drink after is absolute bliss. Acclimatise slowly — don't just jump in.","season":"w"},
  {"id":"5","title":"Host a Rooftop Movie Night","desc":"Set up a projector on a rooftop or balcony. Pick a cult classic. Popcorn is mandatory.","cat":"social","mins":240,"spend":1,"effort":1,"who":"pg","where":"out","light":"night","reach":0,"kit":["Portable projector","Laptop or streaming device","Bluetooth speaker","White sheet or blank wall","Extension lead","Blankets and cushions","Popcorn and drinks"],"tip":"Test the projector setup before guests arrive. Start the film after sunset for best picture. Have a backup indoor plan in case of weather. Fairy lights add great ambiance.","season":"w"},
  {"id":"6","title":"Forest Bathing Session","desc":"Spend 2 hours slowly walking through woodland. No phone. Focus on sounds, smells, textures.","cat":"wellness","mins":60,"spend":0,"effort":1,"who":"s","where":"out","light":"day","reach":1,"kit":["Comfortable walking shoes","Water bottle","Light layers","Journal (optional)"],"tip":"Leave your phone in the car or switch it fully off. Walk at half your normal pace. Stop often. Touch the bark, listen to the birds, smell the earth. This is medicine.","season":""},
  {"id":"7","title":"Urban Photography Safari","desc":"Pick a neighbourhood you've never explored. Document it in 36 photos — like a roll of film.","cat":"urban","mins":240,"spend":0,"effort":1,"who":"s","where":"out","light":"day","reach":1,"kit":["Camera or phone","Comfortable shoes","Portable charger","Small notebook for captions","Water bottle"],"tip":"Limit yourself to 36 shots like a film roll — it forces you to be intentional. Look up, look down, shoot reflections. Talk to locals. The best shots come from curiosity.","season":""},
  {"id":"8","title":"Midnight Stargazing Camp","desc":"Drive to a dark sky area. Lay out blankets and identify constellations. Stay until you see a shooting star.","cat":"outdoor","mins":600,"spend":1,"effort":2,"who":"sp","where":"out","light":"night","reach":2,"kit":["Blankets or sleeping bags","Camping mat","Warm clothes & hat","Star chart app","Red light torch","Hot drinks in a thermos","Binoculars (optional)"],"tip":"Check a dark sky map to find the best spot. Let your eyes adjust for 20 minutes — no screens. A red torch preserves night vision. Best around new moon.","season":""},
  {"id":"9","title":"Cooking Class Roulette","desc":"Search for a random cuisine cooking class in your area. Book the next available one.","cat":"food","mins":240,"spend":2,"effort":1,"who":"sp","where":"in","light":"any","reach":1,"kit":["Apron (usually provided)","Tupperware for leftovers","Notebook for recipes","Open mind"],"tip":"Pick a cuisine you've never cooked before. Many classes include the meal at the end. Check reviews and book a couple of weeks ahead for weekend slots.","season":""},
  {"id":"10","title":"Bike to Breakfast","desc":"Cycle to the furthest cafe you can manage, have a massive breakfast, then cycle back.","cat":"outdoor","mins":240,"spend":1,"effort":2,"who":"sp","where":"out","light":"day","reach":1,"kit":["Bike (obviously)","Helmet","Bike lock","Repair kit & pump","Water bottle","Cash/card","Layers you can stuff in a bag"],"tip":"Pick a cafe 10-20 miles away for a good challenge. Eat well — you need fuel for the return. Check your tyres the night before. Scenic routes > fast routes.","season":""},
  {"id":"11","title":"Volunteer for a Day","desc":"Sign up for a local volunteering opportunity. Beach cleanup, food bank, animal shelter — whatever calls.","cat":"social","mins":600,"spend":0,"effort":1,"who":"pg","where":"any","light":"day","reach":1,"kit":["Comfortable clothes you don't mind getting dirty","Packed lunch & water","Sun protection","Gloves (for outdoor work)","Good attitude"],"tip":"Search local Facebook groups or volunteer websites. Many need no experience. Bring a friend to make it social. You'll feel incredible afterwards.","season":""},
  {"id":"12","title":"Cold Water Challenge","desc":"Find a safe cold water spot and take the plunge. Even 30 seconds counts. The buzz afterwards is unreal.","cat":"wellness","mins":60,"spend":0,"effort":3,"who":"sp","where":"out","light":"day","reach":1,"kit":["Swimsuit","Towel","Warm hat & gloves for after","Hot drink in thermos","Warm dry clothes","Neoprene boots/gloves (optional)","A brave friend"],"tip":"Never go alone. Wade in slowly, control your breathing. Stay in for as long as feels safe — even 30 seconds triggers the endorphin rush. Warm up immediately after.","season":""},
  {"id":"13","title":"Build a Den","desc":"Head into the woods and build a den from fallen branches. Inner child energy required.","cat":"outdoor","mins":240,"spend":0,"effort":1,"who":"pg","where":"out","light":"day","reach":1,"kit":["Gloves","Sturdy shoes","Snacks","Hot drink","Penknife (optional)","Tarp or groundsheet"],"tip":"Use only fallen branches — don't break living trees. Lean long branches against a fallen trunk for a quick A-frame. Make it cosy with leaves on the floor. Best with kids or big kids.","season":""},
  {"id":"14","title":"Live Music Bingo","desc":"Check local listings and go see a band you've never heard of. Bonus points if it's a genre you'd never pick.","cat":"social","mins":240,"spend":1,"effort":1,"who":"pg","where":"in","light":"night","reach":1,"kit":["Cash for entry & drinks","Earplugs (small venues can be loud)","Open mind","Good vibes"],"tip":"Check local venue websites, Dice, or Songkick for gigs tonight. Pubs often have free live music. Go in with zero expectations — that's where the magic is.","season":""},
  {"id":"15","title":"DIY Spa Day","desc":"Make your own face masks, run a bath, light candles. Full pampering. You deserve it.","cat":"wellness","mins":240,"spend":1,"effort":1,"who":"s","where":"in","light":"any","reach":0,"kit":["Candles","Bath salts or bubble bath","Face mask ingredients (honey, oats, avocado)","Fluffy towels","Relaxing playlist","Herbal tea","Cucumber for eyes"],"tip":"Put your phone in another room. Prep everything before you start so you don't have to break the vibe. Honey + oat face mask is simple and effective.","season":""},
  {"id":"16","title":"Geocaching Quest","desc":"Download a geocaching app and find 3 caches near you. Leave something fun behind.","cat":"urban","mins":240,"spend":0,"effort":1,"who":"sp","where":"out","light":"day","reach":1,"kit":["Smartphone with geocaching app","Pen for signing logbooks","Small trinkets to trade","Comfortable shoes","Water"],"tip":"Start with caches rated 1-2 difficulty. Read the hints if you're stuck. Always re-hide the cache exactly as you found it. It's surprisingly addictive.","season":""},
  {"id":"17","title":"Campfire Cooking","desc":"Build a fire (safely & legally) and cook your entire dinner on it. Foil-wrapped potatoes, skewers, the lot.","cat":"food","mins":600,"spend":1,"effort":2,"who":"pg","where":"out","light":"any","reach":2,"kit":["Firesteel or matches","Kindling and firewood","Cooking grate or skewers","Tin foil","Ingredients (potatoes, sausages, veg, marshmallows)","Water for fire safety","Chopping board & knife"],"tip":"Let the fire burn down to embers for cooking — flames are too hot. Foil-wrapped potatoes take ~45 mins in embers. Always have water nearby to extinguish. Check local fire rules.","season":""},
  {"id":"18","title":"Sunrise Yoga on the Beach","desc":"Get to the coast for first light. Roll out a mat and flow with the sound of waves.","cat":"wellness","mins":60,"spend":0,"effort":1,"who":"s","where":"out","light":"any","reach":2,"kit":["Yoga mat","Warm layers","Water bottle","Towel","Phone for guided flow (optional)"],"tip":"Arrive 15 mins before sunrise. Face east. Even a simple sun salutation sequence feels incredible with waves crashing. Dress warmer than you think — beach mornings are cold.","season":""},
  {"id":"19","title":"Graffiti & Street Art Tour","desc":"Map out the best street art in your city. Walk the route, photograph everything, learn the artists.","cat":"urban","mins":240,"spend":0,"effort":1,"who":"sp","where":"out","light":"day","reach":1,"kit":["Camera or phone","Comfortable shoes","Portable charger","Notebook","Water & snack"],"tip":"Google your city + 'street art map' before you go. Instagram location tags are gold for finding murals. Walk slowly — the best pieces are often hidden in side streets and alleys.","season":""},
  {"id":"20","title":"Weekend Microcamp","desc":"Pack light, hike to a wild camping spot, spend one night under the stars. Keep it simple.","cat":"outdoor","mins":2880,"spend":1,"effort":3,"who":"sp","where":"out","light":"any","reach":2,"kit":["Tent or bivvy bag","Sleeping bag & mat","Stove & fuel","Food & water","Head torch","Warm layers","Map & compass","First aid kit","Rubbish bags (leave no trace)"],"tip":"Practice packing light — you carry everything. Arrive at your spot with daylight to spare. Check the weather forecast. Leave no trace. Wild camping rules vary by country — check first.","season":"w"},
  {"id":"21","title":"Silent Morning Walk","desc":"Take a 30-minute walk without headphones or phone use. Notice sounds, smells, and details you normally ignore.","cat":"wellness","mins":60,"spend":0,"effort":1,"who":"s","where":"out","light":"day","reach":0,"kit":["Comfortable shoes"],"tip":"Early mornings are best. Try to spot five things you've never noticed before.","season":""},
  {"id":"22","title":"Three Café Morning","desc":"Visit three different cafés in one morning and rate them for atmosphere, coffee, and pastries.","cat":"urban","mins":240,"spend":2,"effort":1,"who":"sp","where":"in","light":"day","reach":1,"kit":["Notebook","Wallet"],"tip":"Walk between cafés if possible. Sit somewhere different in each one.","season":""},
  {"id":"23","title":"Random Bus Ride","desc":"Get on a bus or train and ride it for 20 minutes. Get off at a random stop and explore the area.","cat":"urban","mins":240,"spend":1,"effort":1,"who":"s","where":"out","light":"day","reach":1,"kit":["Bus pass or contactless card","Snacks","Phone map"],"tip":"Choose somewhere you've never visited before.","season":""},
  {"id":"24","title":"Disposable Camera Day","desc":"Use a disposable camera and take photos throughout the day without reviewing them.","cat":"creative","mins":600,"spend":1,"effort":1,"who":"s","where":"any","light":"day","reach":0,"kit":["Disposable camera"],"tip":"Photograph ordinary things. The surprise later is part of the fun.","season":""},
  {"id":"25","title":"New Fruit Market Challenge","desc":"Visit an international market and buy five fruits or snacks you've never tried before.","cat":"food","mins":60,"spend":1,"effort":1,"who":"sp","where":"any","light":"day","reach":1,"kit":["Shopping bag"],"tip":"Ask the vendor how to eat them.","season":""},
  {"id":"26","title":"Weird Museum Visit","desc":"Find the strangest or most niche museum near you and explore it.","cat":"urban","mins":240,"spend":1,"effort":1,"who":"sp","where":"in","light":"day","reach":1,"kit":["Notebook"],"tip":"Local museums often hide the weirdest collections.","season":""},
  {"id":"27","title":"Cook From One Shop","desc":"Cook a full meal using only ingredients bought from a corner shop or petrol station.","cat":"food","mins":240,"spend":1,"effort":2,"who":"sp","where":"in","light":"any","reach":0,"kit":["Basic cooking tools"],"tip":"Creativity is the goal, not perfection.","season":""},
  {"id":"28","title":"Sunset Photo Walk","desc":"Walk somewhere scenic and photograph the sunset from multiple viewpoints.","cat":"outdoor","mins":60,"spend":0,"effort":1,"who":"s","where":"out","light":"any","reach":0,"kit":["Camera or phone"],"tip":"Cloudy evenings often create the best colours.","season":""},
  {"id":"29","title":"Street Food Lunch","desc":"Eat lunch somewhere you've never eaten before — a food truck, street stall, or tiny café.","cat":"food","mins":60,"spend":1,"effort":1,"who":"s","where":"out","light":"day","reach":1,"kit":["Cash or card"],"tip":"Order something you can't pronounce.","season":""},
  {"id":"30","title":"Public Piano Session","desc":"Find a public piano and try playing something simple or improvised.","cat":"creative","mins":60,"spend":0,"effort":1,"who":"s","where":"in","light":"day","reach":1,"kit":[],"tip":"Even one note at a time counts.","season":""},
  {"id":"31","title":"Vinyl Cover Pick","desc":"Choose a vinyl record purely based on its cover art and listen to the entire album.","cat":"creative","mins":60,"spend":1,"effort":1,"who":"s","where":"in","light":"any","reach":1,"kit":["Record player or streaming"],"tip":"No skipping tracks.","season":""},
  {"id":"32","title":"Local History Walk","desc":"Research a historic site nearby and walk there to learn its story.","cat":"urban","mins":60,"spend":0,"effort":1,"who":"sp","where":"out","light":"day","reach":0,"kit":["Phone for research"],"tip":"Older pubs often have fascinating histories.","season":""},
  {"id":"33","title":"Night Walk Adventure","desc":"Take a walk after dark in a familiar area and notice how different everything feels.","cat":"outdoor","mins":60,"spend":0,"effort":1,"who":"sp","where":"out","light":"night","reach":0,"kit":["Torch"],"tip":"Stick to safe areas.","season":""},
  {"id":"34","title":"Library Wander","desc":"Spend an hour wandering library shelves and pick one book from a random section.","cat":"urban","mins":60,"spend":0,"effort":1,"who":"s","where":"in","light":"day","reach":0,"kit":[],"tip":"Avoid the sections you usually browse.","season":""},
  {"id":"35","title":"Tiny Creative Project","desc":"Spend an hour making something small: clay sculpture, poem, sketch, or collage.","cat":"creative","mins":60,"spend":1,"effort":1,"who":"s","where":"in","light":"any","reach":0,"kit":["Craft materials"],"tip":"Limit time to encourage experimentation.","season":""},
  {"id":"36","title":"Rooftop View Hunt","desc":"Find the highest publicly accessible viewpoint in your area and visit it.","cat":"urban","mins":60,"spend":0,"effort":1,"who":"sp","where":"out","light":"day","reach":1,"kit":[],"tip":"Car parks often have great views.","season":""},
  {"id":"37","title":"Three New Songs","desc":"Listen to three songs from a genre you normally ignore.","cat":"creative","mins":60,"spend":0,"effort":1,"who":"s","where":"any","light":"any","reach":0,"kit":["Music app"],"tip":"Try global charts.","season":""},
  {"id":"38","title":"Park Reading Hour","desc":"Bring a book to a park and read outdoors for one uninterrupted hour.","cat":"wellness","mins":60,"spend":0,"effort":1,"who":"s","where":"out","light":"day","reach":0,"kit":["Book","Blanket"],"tip":"Leave your phone in your bag.","season":"w"},
  {"id":"39","title":"Canal Towpath Walk","desc":"Find your nearest canal and walk the towpath for an hour. Watch the narrowboats, say hello to the ducks, stop at a canalside pub.","cat":"outdoor","mins":240,"spend":0,"effort":1,"who":"sp","where":"out","light":"day","reach":1,"kit":["Comfortable shoes","Waterproof layer","Camera"],"tip":"Most British canals have well-maintained towpaths. Check the Canal & River Trust website for routes near you.","season":""},
  {"id":"40","title":"Car Boot Sale Treasure Hunt","desc":"Get up early on a Sunday and hit a car boot sale. Set a £5 budget and find the most interesting thing you can.","cat":"urban","mins":240,"spend":1,"effort":1,"who":"sp","where":"out","light":"day","reach":1,"kit":["Cash (small notes and coins)","Reusable bags","Early alarm"],"tip":"Arrive early for the best finds. Bring your own bags. Haggling is expected — don't be shy.","season":"w"},
  {"id":"41","title":"National Trust Wander","desc":"Pick a National Trust property you've never visited. Explore the grounds, have a scone in the tearoom, pretend you live there.","cat":"outdoor","mins":600,"spend":2,"effort":1,"who":"sp","where":"out","light":"day","reach":2,"kit":["National Trust membership or entry fee","Walking shoes","Layers","Camera"],"tip":"Many properties have free grounds even without membership. The scones are always worth it. Check for seasonal events.","season":""},
  {"id":"42","title":"Seaside Fish & Chips","desc":"Drive or train to the nearest seaside town. Eat fish and chips on the seafront. Paddle if you're brave enough.","cat":"food","mins":600,"spend":1,"effort":1,"who":"pg","where":"out","light":"day","reach":2,"kit":["Cash for the chippy","Warm layers","Towel for paddling","Windbreaker"],"tip":"Mushy peas and curry sauce are non-negotiable. Sit on the sea wall. Seagulls will try their luck — guard your chips.","season":""},
  {"id":"43","title":"Village Pub Crawl","desc":"Pick three countryside pubs within walking distance of each other. One pint at each. Crisps mandatory.","cat":"social","mins":240,"spend":2,"effort":1,"who":"pg","where":"any","light":"day","reach":2,"kit":["Walking boots","Cash","Ordnance Survey map or phone"],"tip":"Choose pubs with beer gardens for summer. Many villages have circular routes linking two or three pubs. Pace yourself.","season":""},
  {"id":"44","title":"Charity Shop Challenge","desc":"Visit five charity shops in one afternoon. Find the weirdest, best, or most vintage item for under £3.","cat":"urban","mins":240,"spend":1,"effort":1,"who":"sp","where":"in","light":"day","reach":1,"kit":["Cash","Tote bag","An open mind"],"tip":"Oxfam bookshops are goldmines. Check the bric-a-brac section for absolute gems. Cathedral towns tend to have the best charity shops.","season":""},
  {"id":"45","title":"Afternoon Tea Crawl","desc":"Book afternoon tea somewhere fancy. Or make your own with scones, clotted cream, and jam — cream first, obviously.","cat":"food","mins":240,"spend":2,"effort":1,"who":"sp","where":"in","light":"day","reach":1,"kit":["Smart-ish clothes","Appetite","Strong opinions on cream vs jam order"],"tip":"Many hotels do afternoon tea for £20-30pp. Or DIY it properly at home — warm scones, proper clotted cream, loose leaf tea.","season":""},
  {"id":"46","title":"Dawn Chorus Walk","desc":"Set your alarm for 4am in spring. Head to woodland and listen to the birds wake up. It's utterly magical.","cat":"outdoor","mins":60,"spend":0,"effort":2,"who":"s","where":"out","light":"any","reach":1,"kit":["Warm layers","Flask of tea","Bird ID app","Torch for the walk in"],"tip":"Late April to early June is peak dawn chorus season. Arrive before first light. Stand still and just listen. The RSPB website lists guided walks.","season":"w"},
  {"id":"47","title":"Ordnance Survey Adventure","desc":"Open an OS map, close your eyes, point at a spot. Drive there and explore whatever you find.","cat":"outdoor","mins":600,"spend":1,"effort":1,"who":"sp","where":"out","light":"day","reach":2,"kit":["OS map or OS Maps app","Walking boots","Packed lunch","Waterproofs"],"tip":"The pink roads on the map usually lead somewhere interesting. Aim for green areas or blue lines. Pack a flask — you never know what you'll find.","season":""},
  {"id":"48","title":"Wetherspoons Breakfast Tour","desc":"Visit the nearest Wetherspoons you've never been to. Have a full English and rate it out of ten.","cat":"food","mins":60,"spend":1,"effort":1,"who":"sp","where":"in","light":"day","reach":1,"kit":["Appetite","The Wetherspoons app","Low expectations, high spirits"],"tip":"Every Spoons has a different vibe. Check the carpet — there's actually a book about Wetherspoons carpets. Order a coffee refill.","season":""},
  {"id":"49","title":"Hot Air Balloon Sunrise","desc":"Book a dawn balloon flight over the countryside. Float in silence above the fields. Champagne on landing.","cat":"outdoor","mins":240,"spend":3,"effort":1,"who":"sp","where":"out","light":"day","reach":2,"kit":["Warm layers","Camera","Flat shoes","Nerves of steel"],"tip":"Book well in advance — flights depend on weather and get cancelled often. Dress warmer than you'd expect. The silence up there is extraordinary.","season":""},
  {"id":"50","title":"Michelin Star Tasting Menu","desc":"Book the tasting menu at the nearest Michelin-starred restaurant. Go all in. Wine pairing. The lot.","cat":"food","mins":240,"spend":3,"effort":1,"who":"sp","where":"in","light":"any","reach":1,"kit":["Smart clothes","Empty stomach","Appreciation for tiny portions"],"tip":"Book months ahead for popular spots. Let the sommelier choose the wine pairing. Don't fill up on bread.","season":""},
  {"id":"51","title":"Spa Day Escape","desc":"Full spa day at a fancy hotel. Treatments, robes, swimming, zero guilt. You've earned this.","cat":"wellness","mins":600,"spend":3,"effort":1,"who":"sp","where":"in","light":"day","reach":2,"kit":["Swimsuit","Book","Zero obligations"],"tip":"Midweek is cheaper and quieter. Book treatments in advance. Arrive early to use the facilities. Leave your phone in the locker.","season":""},
  {"id":"52","title":"Glamping Weekend","desc":"Book a shepherd's hut, treehouse, or yurt somewhere beautiful. Log burner, hot tub, stars through the skylight.","cat":"outdoor","mins":2880,"spend":3,"effort":1,"who":"sp","where":"out","light":"any","reach":2,"kit":["Cosy clothes","Good food to cook","Board games","Bottle of something nice"],"tip":"Canopy & Stars and Quality Unearthed have brilliant options. Book the one with the hot tub — you won't regret it. Bring better food than you think you need.","season":""},
  {"id":"53","title":"Private Pottery Class","desc":"Book a private wheel-throwing session for two. Get absolutely covered in clay. Keep what you make.","cat":"creative","mins":240,"spend":3,"effort":2,"who":"sp","where":"in","light":"day","reach":1,"kit":["Old clothes you don't mind ruining","Hair tie","Sense of humour"],"tip":"You will be terrible at first. That's the point. The instructor does the hard bit. Your wobbly mug will be your favourite mug.","season":""},
  {"id":"54","title":"Helicopter Scenic Flight","desc":"Twenty minutes in a helicopter over coastline or countryside. See your world from above.","cat":"outdoor","mins":60,"spend":3,"effort":1,"who":"sp","where":"out","light":"day","reach":2,"kit":["Camera","Sunglasses","Layers"],"tip":"Book on a clear day. Sit on the side facing the view. It's louder than you expect — enjoy it. Many airfields offer gift vouchers.","season":""},
  {"id":"55","title":"West End Show & Dinner","desc":"Train to London. Pre-theatre dinner somewhere smart. Top show. Late train home. Proper night out.","cat":"social","mins":600,"spend":3,"effort":1,"who":"sp","where":"in","light":"night","reach":2,"kit":["Smart outfit","Pre-booked tickets","Train tickets","Comfortable shoes for the walk"],"tip":"Book show tickets on TodayTix for last-minute deals. Pre-theatre menus are great value. Covent Garden and Soho have the best options nearby.","season":""},
  {"id":"56","title":"English Vineyard Tour","desc":"Visit an English vineyard. Tour the vines, taste the wines, bring bottles home. Sussex and Kent are superb.","cat":"food","mins":240,"spend":3,"effort":1,"who":"sp","where":"out","light":"day","reach":2,"kit":["Designated driver or taxi plan","Tote bag for bottles","Cardigan for the cellar"],"tip":"English sparkling wine rivals Champagne now. Chapel Down, Nyetimber, and Ridgeview are all brilliant. Book the full tour with tasting.","season":"w"},
  {"id":"57","title":"Classic Car Hire Day","desc":"Rent a classic car for the day — an E-Type, MG, or Mini — and drive a scenic route through the countryside.","cat":"outdoor","mins":600,"spend":3,"effort":2,"who":"sp","where":"out","light":"day","reach":2,"kit":["Driving licence","Sunglasses","Packed lunch","Playlist on your phone"],"tip":"Great Escape Cars and Classic Car Hire have excellent fleets. Plan a route with scenic stops. The Cotswolds and Lake District are perfect for this.","season":""},
  {"id":"58","title":"Seaside Hotel Overnight","desc":"Book a room with a sea view somewhere lovely. Fish supper. Morning swim. Home by lunch. Mini holiday.","cat":"wellness","mins":2880,"spend":3,"effort":1,"who":"sp","where":"any","light":"any","reach":2,"kit":["Overnight bag","Swimsuit","Walking shoes","Book"],"tip":"Whitstable, St Ives, Robin Hood's Bay, Aldeburgh — all have gorgeous small hotels. Off-season midweek is surprisingly affordable. Ask for the room with the best view.","season":""},
  {"id":"59","title":"Forage & Cook","desc":"Learn to identify three wild edibles — blackberries, wild garlic, elderflower — then cook something with them.","cat":"food","mins":240,"spend":0,"effort":2,"who":"sp","where":"out","light":"day","reach":1,"kit":["Foraging guide or app","Basket or bag","Knife","Kitchen access"],"tip":"Only pick what you can 100% identify. Wild garlic pesto is foolproof. Spring and autumn are the best seasons. Leave plenty for wildlife.","season":""},
  {"id":"60","title":"Sleep Under the Stars","desc":"No tent. Just a sleeping bag, a mat, and the sky above. Find a safe spot and spend one night sleeping outdoors.","cat":"outdoor","mins":600,"spend":0,"effort":3,"who":"s","where":"out","light":"night","reach":1,"kit":["Sleeping bag","Bivvy bag or tarp","Roll mat","Warm layers","Head torch","Water"],"tip":"Check the forecast obsessively. A garden counts if you're nervous. The first time is the hardest — after that you'll crave it. Best on warm, clear nights.","season":"w"},
  {"id":"61","title":"Handwritten Letter Day","desc":"Write three handwritten letters to people you appreciate. Post them. No texts, no emails — proper ink on paper.","cat":"creative","mins":60,"spend":1,"effort":1,"who":"s","where":"in","light":"any","reach":0,"kit":["Nice paper or cards","Pen","Stamps","Addresses"],"tip":"Write to someone who wouldn't expect it. A handwritten letter in 2025 is genuinely surprising. Use proper stamps, not a meter.","season":""},
  {"id":"62","title":"Farmers' Market Feast","desc":"Buy all the ingredients for one meal from a farmers' market. Talk to every stall holder. Cook it that evening.","cat":"food","mins":240,"spend":2,"effort":1,"who":"sp","where":"out","light":"day","reach":1,"kit":["Reusable bags","Cash","Cool bag for meat/dairy","Recipe idea"],"tip":"Go early for the best picks. Ask vendors what's in season and how they'd cook it. You'll eat better than any restaurant.","season":""},
  {"id":"63","title":"Bridge Jump","desc":"Find a safe, legal spot to jump off a bridge or rock into deep water. The terror lasts 2 seconds. The buzz lasts all day.","cat":"outdoor","mins":240,"spend":0,"effort":3,"who":"pg","where":"out","light":"day","reach":2,"kit":["Swimsuit","Towel","Shoes for climbing back up","Brave friends","First aid kit"],"tip":"Only jump where others have jumped safely before. Check depth first — always feet first. Start low. Never jump alone. The fear is the point.","season":"w"},
  {"id":"64","title":"Technology-Free Day","desc":"Turn off every screen for 24 hours. Read, walk, cook, talk. Rediscover what boredom actually feels like.","cat":"wellness","mins":600,"spend":0,"effort":2,"who":"s","where":"any","light":"any","reach":0,"kit":["A book","Board games","Pen and paper","An alarm clock that isn't your phone"],"tip":"Tell people in advance so they don't worry. The first two hours are the hardest. By evening you'll feel oddly peaceful. Do it on a weekend.","season":""},
  {"id":"65","title":"Waterfall Hunt","desc":"Find the nearest waterfall you've never visited. Hike to it. Stand close enough to feel the spray.","cat":"outdoor","mins":240,"spend":0,"effort":2,"who":"sp","where":"out","light":"day","reach":2,"kit":["Waterproof jacket","Sturdy shoes","Camera","Packed lunch","Dry clothes"],"tip":"The UK has hundreds of waterfalls — most are free to visit. Go after heavy rain for maximum drama. The sound alone is worth the walk.","season":""},
  {"id":"66","title":"Sunrise-to-Sunset Challenge","desc":"Be outside for both sunrise and sunset in one day. Fill the hours between with whatever feels right.","cat":"outdoor","mins":600,"spend":0,"effort":2,"who":"s","where":"out","light":"day","reach":1,"kit":["Layers for early morning","Food for the whole day","Camera","Blanket","Journal"],"tip":"In summer that's 16+ hours of daylight. Plan a few anchor activities but leave room for spontaneity. You'll feel like you lived a whole week in one day.","season":"w"},
  {"id":"67","title":"Stranger's Recommendation","desc":"Ask a stranger for their favourite local spot — café, walk, viewpoint, anything. Go there immediately.","cat":"social","mins":240,"spend":1,"effort":1,"who":"s","where":"out","light":"day","reach":0,"kit":["Friendly attitude","Walking shoes","Open schedule"],"tip":"People love being asked. Dog walkers, café owners, and shopkeepers give the best recommendations. Follow through on the first suggestion you get.","season":""},
  {"id":"68","title":"Learn One Survival Skill","desc":"Spend an afternoon mastering one bushcraft skill: fire by friction, knot tying, shelter building, or water purification.","cat":"outdoor","mins":240,"spend":0,"effort":2,"who":"sp","where":"out","light":"day","reach":0,"kit":["YouTube tutorial downloaded","Materials for chosen skill","Patience","Outdoor space"],"tip":"Fire by friction is the most rewarding but hardest. Start with knot tying — it's useful immediately. Bowline, clove hitch, and taut-line are the essential three.","season":""},
  {"id":"69","title":"Full Moon Walk","desc":"Wait for a full moon. Go for a walk without a torch. Let your eyes adjust. The world looks completely different.","cat":"outdoor","mins":60,"spend":0,"effort":1,"who":"sp","where":"out","light":"night","reach":1,"kit":["Dark clothing","Quiet shoes","Warm layers","Torch for emergencies only"],"tip":"Check the moon phase calendar. Clear skies and open countryside are best. Give your eyes 15 minutes to adjust. You'll be amazed how much you can see.","season":""},
  {"id":"70","title":"River Picnic & Paddle","desc":"Find a gentle river or stream. Pack a picnic. Eat on the bank. Paddle in the shallows. Skip stones.","cat":"outdoor","mins":240,"spend":0,"effort":1,"who":"sp","where":"out","light":"day","reach":1,"kit":["Picnic food","Blanket","Towel","Water shoes or old trainers","Sun cream"],"tip":"Bring a reusable cup for scooping cold water over yourself. Flat stones skip best. Find a spot with a mix of sun and shade.","season":"w"},
  {"id":"71","title":"Blindfold Taste Test","desc":"Buy five things from a deli or market. Blindfold your partner or friend. Make them guess every item.","cat":"food","mins":60,"spend":1,"effort":1,"who":"sp","where":"in","light":"any","reach":0,"kit":["Blindfold","Selection of foods","Plates and utensils","Napkins"],"tip":"Mix textures and flavours — cured meats, cheeses, olives, chocolate, pickles. The guessing gets hilarious. Works brilliantly as a date night.","season":""},
  {"id":"72","title":"Kayak or Canoe a River","desc":"Hire a kayak or canoe and paddle a stretch of river you've never seen from the water. Everything looks different from a boat.","cat":"outdoor","mins":240,"spend":2,"effort":2,"who":"sp","where":"out","light":"day","reach":2,"kit":["Change of clothes","Dry bag for phone","Water","Sun cream","Shoes that can get wet"],"tip":"Many rivers have hire-and-collect services so you don't paddle back. Check for weirs and portages. The Wye, Thames, and Norfolk Broads are all brilliant.","season":"w"},
  {"id":"m1","title":"Three left turns","desc":"Leave your door and turn left at the first three junctions. From there, turn right whenever you can until you reach a street you have never walked down.","cat":"urban","mins":30,"spend":0,"effort":1,"who":"sp","where":"out","light":"any","reach":0,"kit":["Comfortable shoes"],"tip":"","season":""},
  {"id":"m2","title":"Alphabet street hunt","desc":"Find something on your route for every letter of the alphabet: shop signs, street names, doorplates. Race a friend, or race yourself.","cat":"urban","mins":90,"spend":0,"effort":1,"who":"spg","where":"out","light":"day","reach":0,"kit":["Phone or notebook"],"tip":"","season":""},
  {"id":"m3","title":"Oldest thing on the street","desc":"Track down the oldest building, tree or marker within a ten-minute walk, then find out roughly when it was put there.","cat":"urban","mins":90,"spend":0,"effort":1,"who":"sp","where":"out","light":"day","reach":0,"kit":["Phone for the lookup"],"tip":"","season":""},
  {"id":"m4","title":"Cut-through collector","desc":"Follow every alley, footpath and cut-through within a mile of home that you have always walked past.","cat":"urban","mins":90,"spend":0,"effort":2,"who":"sp","where":"out","light":"day","reach":0,"kit":["Sturdy shoes"],"tip":"","season":""},
  {"id":"m5","title":"Lit windows loop","desc":"After dark, walk a loop and pick the three best-lit things you pass: a window, a shop sign, a streetlight. Describe each in one line when you get back.","cat":"urban","mins":90,"spend":0,"effort":1,"who":"sp","where":"out","light":"night","reach":0,"kit":["Torch, warm layers"],"tip":"","season":"c"},
  {"id":"m6","title":"Sun-down spot","desc":"Find the best place within thirty minutes' walk to watch the sun set, and be there before it goes.","cat":"outdoor","mins":90,"spend":0,"effort":1,"who":"sp","where":"out","light":"day","reach":0,"kit":["A flask if it is cold"],"tip":"","season":""},
  {"id":"m7","title":"Map from memory","desc":"Draw your neighbourhood from memory, then walk it with the map and correct everything you got wrong.","cat":"creative","mins":90,"spend":0,"effort":1,"who":"sp","where":"any","light":"day","reach":0,"kit":["Paper and a pen"],"tip":"","season":""},
  {"id":"m8","title":"Next train out","desc":"Check the departures board at your nearest station, take the first train under an hour away, and spend the day wherever it drops you.","cat":"urban","mins":600,"spend":2,"effort":2,"who":"sp","where":"out","light":"day","reach":2,"kit":["Rail fare, a charged phone"],"tip":"","season":""},
  {"id":"m9","title":"Follow the water","desc":"Pick the nearest river, canal or stream and follow it for as far as you can before you have to turn round.","cat":"outdoor","mins":240,"spend":0,"effort":2,"who":"spg","where":"out","light":"day","reach":1,"kit":["Snacks and water"],"tip":"","season":""},
  {"id":"m10","title":"Pocket zine","desc":"Fold one sheet of A4 into an eight-page mini zine about your week, then give it to someone.","cat":"creative","mins":90,"spend":0,"effort":1,"who":"spg","where":"in","light":"any","reach":0,"kit":["One sheet of paper, scissors, pens"],"tip":"","season":""},
  {"id":"m11","title":"Cardboard landmark","desc":"Build a model of a real landmark, or a place that does not exist, out of nothing but recycling.","cat":"creative","mins":90,"spend":0,"effort":1,"who":"spg","where":"in","light":"any","reach":0,"kit":["Cardboard, tape, scissors"],"tip":"","season":""},
  {"id":"m12","title":"Postcard to future you","desc":"Write a postcard to yourself about what you hope is true in a month, and post it.","cat":"creative","mins":30,"spend":1,"effort":1,"who":"sp","where":"any","light":"any","reach":0,"kit":["Postcard, stamp"],"tip":"","season":""},
  {"id":"m13","title":"Three ways to draw a mug","desc":"Draw one object three times: ten minutes, three minutes, then thirty seconds with your other hand.","cat":"creative","mins":30,"spend":0,"effort":1,"who":"spg","where":"in","light":"any","reach":0,"kit":["Paper, pencil"],"tip":"","season":""},
  {"id":"m14","title":"Fix the thing","desc":"Pick the object you have been ignoring for months, such as a wobbly shelf, a squeaky hinge or a missing button, and fix it today.","cat":"creative","mins":90,"spend":0,"effort":2,"who":"sp","where":"in","light":"any","reach":0,"kit":["Whatever the job needs"],"tip":"","season":""},
  {"id":"m15","title":"Playlist for a stranger","desc":"Describe an imaginary person in one sentence, then make a ten-track playlist that suits them exactly.","cat":"creative","mins":30,"spend":0,"effort":1,"who":"sp","where":"any","light":"any","reach":0,"kit":["A music app"],"tip":"","season":""},
  {"id":"m16","title":"Ten-second film","desc":"Make a stop-motion film at least ten seconds long using a phone and objects from around the house.","cat":"creative","mins":90,"spend":0,"effort":1,"who":"spg","where":"in","light":"any","reach":0,"kit":["Phone, something to prop it on"],"tip":"","season":""},
  {"id":"m17","title":"Jam-jar lanterns","desc":"Make a few jam-jar lanterns, then put them along a path or doorstep as the light fades.","cat":"creative","mins":90,"spend":1,"effort":1,"who":"spg","where":"any","light":"night","reach":0,"kit":["Jars, tea lights, string"],"tip":"","season":"c"},
  {"id":"m18","title":"Loaf from scratch","desc":"Bake a loaf of bread from flour, water, yeast and salt, and eat the first slice warm.","cat":"food","mins":240,"spend":1,"effort":2,"who":"spg","where":"in","light":"any","reach":0,"kit":["Flour, yeast, salt, an oven"],"tip":"","season":""},
  {"id":"m19","title":"Seed bombs","desc":"Mix compost, clay and wildflower seeds into small balls, then drop them in a scruffy patch of ground you have permission to brighten.","cat":"outdoor","mins":90,"spend":1,"effort":1,"who":"spg","where":"any","light":"day","reach":0,"kit":["Compost, clay, wildflower seeds"],"tip":"","season":"w"},
  {"id":"m20","title":"Back-of-the-cupboard dinner","desc":"Cook a meal from the three oldest things in your kitchen, plus staples. No shopping allowed.","cat":"food","mins":90,"spend":0,"effort":1,"who":"spg","where":"in","light":"any","reach":0,"kit":["Whatever is in the cupboard"],"tip":"","season":""},
  {"id":"m21","title":"Cheapest-on-the-menu lunch","desc":"Eat somewhere you have never been and order the cheapest thing on the menu. Share it, or add the second cheapest.","cat":"food","mins":90,"spend":1,"effort":1,"who":"sp","where":"in","light":"day","reach":1,"kit":["Cash or card"],"tip":"","season":""},
  {"id":"m22","title":"Unknown aisle","desc":"Visit a food shop from a cuisine you rarely cook, buy three things you cannot identify, then cook with all of them.","cat":"food","mins":240,"spend":1,"effort":1,"who":"sp","where":"any","light":"day","reach":1,"kit":["A shopping bag"],"tip":"","season":""},
  {"id":"m23","title":"Flask picnic","desc":"Take a flask of something hot and a sandwich to the best view you can reach and eat it slowly.","cat":"food","mins":90,"spend":1,"effort":1,"who":"spg","where":"out","light":"day","reach":1,"kit":["Flask, a blanket"],"tip":"","season":"c"},
  {"id":"m24","title":"Hot drink hop","desc":"Visit three places for a hot drink, rate each out of ten, and crown a winner.","cat":"food","mins":240,"spend":2,"effort":1,"who":"spg","where":"out","light":"day","reach":1,"kit":["Enough for three drinks"],"tip":"","season":"c"},
  {"id":"m25","title":"Ice cream in the cold","desc":"Walk to get an ice cream on the coldest day this week and eat it outside.","cat":"food","mins":30,"spend":1,"effort":1,"who":"spg","where":"out","light":"day","reach":0,"kit":["Gloves"],"tip":"","season":"c"},
  {"id":"m26","title":"Forage and bake","desc":"Pick blackberries, apples or other fruit you can identify with total certainty, then bake something with it.","cat":"food","mins":240,"spend":1,"effort":2,"who":"spg","where":"out","light":"day","reach":1,"kit":["Bag, flour, butter, sugar"],"tip":"","season":"w"},
  {"id":"m27","title":"Cook a country","desc":"Close your eyes, point at a map, and cook a dish from wherever your finger lands.","cat":"food","mins":240,"spend":1,"effort":2,"who":"spg","where":"in","light":"any","reach":0,"kit":["Ingredients for one dish"],"tip":"","season":""},
  {"id":"m28","title":"Breakfast for dinner","desc":"Eat breakfast food for dinner tonight, or dinner food for breakfast tomorrow, and see which version wins.","cat":"food","mins":30,"spend":0,"effort":1,"who":"spg","where":"in","light":"any","reach":0,"kit":["Eggs, toast, imagination"],"tip":"","season":""},
  {"id":"m29","title":"Hill repeats","desc":"Find the steepest hill within a mile and walk or jog up it five times, with a slow stroll down each time.","cat":"outdoor","mins":30,"spend":0,"effort":3,"who":"sp","where":"out","light":"any","reach":0,"kit":["Decent footwear"],"tip":"","season":""},
  {"id":"m30","title":"Whole-album dance","desc":"Put on one full album and dance in the living room until it ends.","cat":"wellness","mins":90,"spend":0,"effort":2,"who":"spg","where":"in","light":"any","reach":0,"kit":["An album and a bit of space"],"tip":"","season":""},
  {"id":"m31","title":"End of the cycle path","desc":"Follow the nearest signed cycle route as far as it goes, then ride back.","cat":"outdoor","mins":240,"spend":0,"effort":2,"who":"spg","where":"out","light":"day","reach":1,"kit":["Bike, helmet, puncture kit"],"tip":"","season":""},
  {"id":"m32","title":"Playground circuit","desc":"Use the park equipment as a gym: five rounds of climbing, pull-ups, balancing and swinging.","cat":"outdoor","mins":30,"spend":0,"effort":2,"who":"spg","where":"out","light":"day","reach":0,"kit":["Trainers"],"tip":"","season":""},
  {"id":"m33","title":"No-destination walk","desc":"Walk for ninety minutes with no destination and never retrace a step.","cat":"outdoor","mins":90,"spend":0,"effort":2,"who":"sp","where":"out","light":"day","reach":0,"kit":["Good shoes"],"tip":"","season":""},
  {"id":"m34","title":"First frost walk","desc":"Go out early to find frost on the grass and keep walking until the sun clears it.","cat":"outdoor","mins":30,"spend":0,"effort":1,"who":"sp","where":"out","light":"day","reach":0,"kit":["Warm layers"],"tip":"","season":"c"},
  {"id":"m35","title":"Park kick-about","desc":"Take a ball or frisbee to the park and play for an hour, however badly.","cat":"outdoor","mins":90,"spend":0,"effort":2,"who":"pg","where":"out","light":"day","reach":0,"kit":["A ball or frisbee"],"tip":"","season":""},
  {"id":"m36","title":"Rain walk","desc":"Dress properly and go out in the rain on purpose for thirty minutes. Jump in at least one puddle.","cat":"outdoor","mins":30,"spend":0,"effort":2,"who":"spg","where":"out","light":"any","reach":0,"kit":["Waterproofs"],"tip":"","season":""},
  {"id":"m37","title":"Early summit","desc":"Climb the nearest hill or high point before nine in the morning and have breakfast at the top.","cat":"outdoor","mins":240,"spend":1,"effort":3,"who":"pg","where":"out","light":"day","reach":1,"kit":["Breakfast in a bag, layers"],"tip":"","season":""},
  {"id":"m38","title":"Sit spot","desc":"Sit in one outdoor spot for thirty minutes and list everything you see, hear and smell.","cat":"wellness","mins":30,"spend":0,"effort":1,"who":"sp","where":"out","light":"day","reach":0,"kit":["A notebook"],"tip":"","season":""},
  {"id":"m39","title":"Twenty of one colour","desc":"Pick a colour and find twenty examples of it within half an hour.","cat":"outdoor","mins":30,"spend":0,"effort":1,"who":"spg","where":"out","light":"day","reach":0,"kit":["Phone or notebook"],"tip":"","season":""},
  {"id":"m40","title":"Naked-eye stargazing","desc":"Find a dark spot and identify three constellations or planets without a telescope.","cat":"outdoor","mins":90,"spend":0,"effort":1,"who":"spg","where":"out","light":"night","reach":1,"kit":["A star app, a warm coat"],"tip":"","season":""},
  {"id":"m41","title":"Listening walk","desc":"Walk for twenty minutes without headphones and write down every distinct sound you hear.","cat":"wellness","mins":30,"spend":0,"effort":1,"who":"sp","where":"out","light":"day","reach":0,"kit":["A notebook"],"tip":"","season":""},
  {"id":"m42","title":"Museum staring contest","desc":"Visit a free museum or gallery, choose one object, and look at it for ten full minutes.","cat":"urban","mins":90,"spend":0,"effort":1,"who":"sp","where":"in","light":"day","reach":1,"kit":["Opening hours checked"],"tip":"","season":""},
  {"id":"m43","title":"One spot, twelve angles","desc":"Take twelve photos of the same spot from twelve different heights and angles.","cat":"creative","mins":30,"spend":0,"effort":1,"who":"sp","where":"any","light":"day","reach":0,"kit":["Phone camera"],"tip":"","season":""},
  {"id":"m44","title":"Bench stories","desc":"Sit on a bench and invent a short story for each of three strangers who pass.","cat":"creative","mins":30,"spend":0,"effort":1,"who":"sp","where":"out","light":"day","reach":0,"kit":["Nothing but patience"],"tip":"","season":""},
  {"id":"m45","title":"Dark park listen","desc":"Stand still in a dark park or field for ten minutes and listen for owls and foxes.","cat":"outdoor","mins":90,"spend":0,"effort":1,"who":"spg","where":"out","light":"night","reach":1,"kit":["Warm layers, a torch"],"tip":"","season":"c"},
  {"id":"m46","title":"Pond dip","desc":"Look closely at one pond, rock pool or stream for half an hour and find five living things.","cat":"outdoor","mins":90,"spend":0,"effort":1,"who":"spg","where":"out","light":"day","reach":1,"kit":["Magnifier, a net or a jar"],"tip":"","season":"w"},
  {"id":"m47","title":"Sunrise stillness","desc":"Be outside before sunrise and watch the sky change until the sun is properly up.","cat":"wellness","mins":30,"spend":0,"effort":1,"who":"sp","where":"out","light":"any","reach":0,"kit":["A warm drink"],"tip":"","season":""},
  {"id":"m48","title":"Three local tips","desc":"Ask three people you meet (a shopkeeper, a neighbour, a dog walker) for their favourite local spot, then visit one.","cat":"social","mins":90,"spend":0,"effort":1,"who":"sp","where":"out","light":"day","reach":0,"kit":["Nothing at all"],"tip":"","season":""},
  {"id":"m49","title":"Doorstep gift","desc":"Bake or buy something small and leave it with a note for a neighbour.","cat":"social","mins":90,"spend":1,"effort":1,"who":"sp","where":"out","light":"any","reach":0,"kit":["Something to give, a card"],"tip":"","season":""},
  {"id":"m50","title":"Call someone you have lost touch with","desc":"Phone someone you have not spoken to in a year and ask what the best part of their year has been.","cat":"social","mins":30,"spend":0,"effort":1,"who":"s","where":"any","light":"any","reach":0,"kit":["A phone and ten spare minutes"],"tip":"","season":""},
  {"id":"m51","title":"House-rule game night","desc":"Play a game you know well, but each person invents one new rule before it starts.","cat":"social","mins":90,"spend":0,"effort":1,"who":"pg","where":"in","light":"night","reach":0,"kit":["A board or card game"],"tip":"","season":""},
  {"id":"m52","title":"Skill swap","desc":"Teach someone something in twenty minutes and ask them to do the same in return.","cat":"social","mins":90,"spend":0,"effort":1,"who":"pg","where":"in","light":"any","reach":0,"kit":["Whatever you are teaching"],"tip":"","season":""},
  {"id":"m53","title":"Litter-pick morning","desc":"Fill a few bags with litter from a park or street near you, and chat to anyone who stops to say thanks.","cat":"social","mins":240,"spend":0,"effort":2,"who":"spg","where":"out","light":"day","reach":1,"kit":["Gloves, bin bags"],"tip":"","season":""},
  {"id":"m54","title":"Five sincere compliments","desc":"Give five specific compliments to five different people today and notice what happens.","cat":"social","mins":30,"spend":0,"effort":1,"who":"sp","where":"any","light":"any","reach":0,"kit":["A little courage"],"tip":"","season":""},
  {"id":"m55","title":"Photo-album evening","desc":"Open an old photo folder or album with someone and tell the stories behind six pictures.","cat":"social","mins":90,"spend":0,"effort":1,"who":"pg","where":"in","light":"night","reach":0,"kit":["Photos, a hot drink"],"tip":"","season":""},
  {"id":"m56","title":"Quiz night solo","desc":"Turn up to a pub quiz alone and ask to join the team that has a spare seat.","cat":"social","mins":240,"spend":1,"effort":1,"who":"s","where":"in","light":"night","reach":1,"kit":["Cash for a drink"],"tip":"","season":""},
  {"id":"m57","title":"Park-bench hello","desc":"Say hello to everyone you pass on a thirty-minute walk and keep a tally of who answers.","cat":"social","mins":30,"spend":0,"effort":1,"who":"sp","where":"out","light":"day","reach":0,"kit":["A friendly face"],"tip":"","season":""}
],
kids:[
  {"id":"k1","title":"Puddle Jumping Safari","desc":"Put on wellies and waterproofs. Find the biggest puddles in your area and jump in every single one. Measure the splashes.","cat":"outdoor","mins":60,"spend":0,"effort":1,"who":"sp","where":"out","light":"day","reach":0,"kit":["Wellies","Waterproof jacket & trousers","Spare clothes","Towel","Hot chocolate for after"],"tip":"Toddlers will want to do this forever. Bring spare socks. A puddle-depth measuring stick adds extra fun.","season":"","ages":["toddler","child"]},
  {"id":"k2","title":"Bug Hotel Building","desc":"Collect sticks, pinecones, bark, and leaves. Build a bug hotel in the garden or a local green space. Check back weekly for guests.","cat":"creative","mins":240,"spend":0,"effort":1,"who":"pg","where":"any","light":"day","reach":0,"kit":["Wooden pallet or old box","Sticks, bamboo canes","Pinecones, bark, dried leaves","String or wire","Magnifying glass"],"tip":"Layer different materials — each attracts different bugs. Put it somewhere sheltered. Perfect for a school holiday project.","season":"","ages":["child","teenager"]},
  {"id":"k3","title":"Sensory Nature Walk","desc":"A slow walk focused on touch, smell, sound, and sight. Collect treasures in a bag. Name the colours you find.","cat":"wellness","mins":60,"spend":0,"effort":1,"who":"sp","where":"out","light":"day","reach":0,"kit":["Pram or baby carrier","Collection bag","Blanket for sitting","Snacks","Wet wipes"],"tip":"For babies, hold leaves and flowers near them to touch and smell. Toddlers love collecting — give them a little bag. No rush.","season":"","ages":["baby","toddler"]},
  {"id":"k4","title":"Treasure Map Adventure","desc":"Draw a treasure map of your garden or local park. Hide clues and small prizes. Let the kids follow the trail.","cat":"outdoor","mins":240,"spend":1,"effort":1,"who":"pg","where":"out","light":"day","reach":0,"kit":["Paper & pens for map","Small prizes/treats to hide","Ziplock bags for clues","Compass (optional)","Pirate costumes (optional but recommended)"],"tip":"Draw the map on tea-stained paper for authenticity. Use picture clues for younger kids. Hide the final treasure well.","season":"","ages":["child"]},
  {"id":"k5","title":"Campfire & S'mores","desc":"Build a safe campfire (or use a fire pit). Toast marshmallows, make s'mores, tell stories. Pure magic.","cat":"food","mins":240,"spend":1,"effort":1,"who":"pg","where":"out","light":"night","reach":0,"kit":["Fire pit or safe fire area","Firewood & kindling","Marshmallows","Chocolate & biscuits","Long roasting sticks","Water bucket for safety","Blankets"],"tip":"Supervise constantly. Teach kids fire safety first. Whittle sticks together for extra adventure points. Works in garden or campsite.","season":"","ages":["child","teenager"]},
  {"id":"k6","title":"Rock Painting & Hiding","desc":"Paint rocks with bright designs, then hide them around your neighbourhood for others to find. It's art meets geocaching.","cat":"creative","mins":240,"spend":1,"effort":1,"who":"sp","where":"any","light":"day","reach":0,"kit":["Smooth rocks","Acrylic paints or paint pens","Clear varnish/sealant","Newspaper to protect surfaces","Brushes"],"tip":"Toddlers can do handprints. Older kids love detailed designs. Write 'AdventureSpark' on the back! Great rainy day activity before hiding them.","season":"","ages":["toddler","child","teenager"]},
  {"id":"k7","title":"Stargazing Blanket Night","desc":"Lay out blankets in the garden after dark. Identify constellations, look for satellites, make up your own star stories.","cat":"outdoor","mins":60,"spend":0,"effort":1,"who":"pg","where":"out","light":"night","reach":0,"kit":["Blankets & sleeping bags","Hot chocolate","Star chart app","Red torch","Warm clothes & hats","Binoculars (optional)"],"tip":"Best on clear, moonless nights. The ISS passes overhead regularly — check NASA's tracker. Let kids make up their own constellation stories.","season":"","ages":["child","teenager"]},
  {"id":"k8","title":"Barefoot Trail Walk","desc":"Find or make a barefoot sensory trail — mud, grass, sand, pebbles, water. Walk it blindfolded for extra thrills.","cat":"wellness","mins":60,"spend":0,"effort":1,"who":"pg","where":"out","light":"day","reach":1,"kit":["Various textures (if making your own)","Towel","Water for foot washing","Blindfold (optional)","First aid kit"],"tip":"Check the path for sharp objects first. Toddlers won't need blindfolds — it's magical enough barefoot. Many country parks have barefoot trails.","season":"w","ages":["toddler","child"]},
  {"id":"k9","title":"Build & Sail Stick Boats","desc":"Build boats from sticks, leaves, and string. Find a stream and race them. Cheer loudly. Repeat.","cat":"creative","mins":240,"spend":0,"effort":1,"who":"pg","where":"out","light":"day","reach":1,"kit":["Sticks and twigs","Large leaves for sails","String or rubber bands","Penknife (for adults)","Wellies"],"tip":"A Y-shaped stick with a leaf sail works brilliantly. Find a gentle stream with a clear section. Mark a start and finish line.","season":"","ages":["child","teenager"]},
  {"id":"k10","title":"Pram-Friendly Nature Trail","desc":"Find an accessible, pram-friendly trail through woodland or along a river. Stop to point out birds, flowers, and squirrels.","cat":"outdoor","mins":60,"spend":0,"effort":1,"who":"sp","where":"out","light":"day","reach":1,"kit":["All-terrain pram or carrier","Nappy bag","Snacks & milk","Blanket","Rain cover","Camera"],"tip":"Many national parks and nature reserves have pram-friendly routes — check their websites. Go at baby's pace. Stop when they're interested in something.","season":"","ages":["baby"]},
  {"id":"k11","title":"Fairy Garden Building","desc":"Create a miniature fairy garden in a pot, tree stump, or garden corner. Use natural materials and tiny accessories.","cat":"creative","mins":240,"spend":1,"effort":1,"who":"sp","where":"any","light":"day","reach":0,"kit":["Plant pot or container","Soil and small plants","Pebbles and moss","Tiny accessories (optional)","Sticks for fences","Imagination"],"tip":"Use acorn cups as bowls, twigs as fences, moss as carpet. Toddlers love the tiny world aspect. Check on your fairy garden weekly.","season":"","ages":["toddler","child"]},
  {"id":"k12","title":"Teen Adventure Challenge","desc":"Set up a series of outdoor challenges: fire starting, shelter building, navigation, cooking. Earn badges for each.","cat":"outdoor","mins":600,"spend":1,"effort":2,"who":"pg","where":"out","light":"day","reach":1,"kit":["Map & compass","Firesteel","Tarp for shelter","Cooking supplies","First aid kit","Badge/reward system","Pen & paper for challenges"],"tip":"Teenagers respond to real challenge and autonomy. Let them lead. The fire-starting and shelter-building feel genuinely cool. Make certificates.","season":"","ages":["teenager"]},
  {"id":"k13","title":"Duck Feeding & Pond Dipping","desc":"Visit a local pond. Feed the ducks (with proper duck food, not bread!), then try pond dipping with a net.","cat":"outdoor","mins":60,"spend":0,"effort":1,"who":"sp","where":"out","light":"day","reach":0,"kit":["Duck food (sweetcorn, peas, oats)","Small fishing net","White tray or bucket","Magnifying glass","Wellies","Change of clothes"],"tip":"Bread is bad for ducks — bring frozen peas or sweetcorn instead. Pond dipping: gently sweep the net through weeds. You'll find amazing things.","season":"","ages":["baby","toddler","child"]},
  {"id":"k14","title":"Kitchen Disco","desc":"Clear the kitchen floor. Put on a playlist. Have a full-on family dance party. Glow sticks optional but encouraged.","cat":"social","mins":60,"spend":0,"effort":1,"who":"pg","where":"in","light":"any","reach":0,"kit":["Music speaker","Glow sticks or fairy lights","Space to dance","Snacks & drinks","Silly costumes (optional)"],"tip":"Works for ALL ages. Babies love being held and danced with. Toddlers go wild. Teens pretend they hate it but secretly love it. Play everyone's requests.","season":"","ages":["baby","toddler","child","teenager"]},
  {"id":"k15","title":"Nature Scavenger Hunt","desc":"Print or draw a list of things to find: pinecone, feather, round stone, something red, animal tracks. First to complete wins.","cat":"outdoor","mins":240,"spend":0,"effort":1,"who":"pg","where":"out","light":"day","reach":0,"kit":["Printed scavenger hunt list","Bag for collecting","Pencil for ticking off","Camera","Magnifying glass"],"tip":"Make picture lists for younger kids, word lists for older ones. Include some hard-to-find items for a challenge. Do it as teams for extra competition.","season":"","ages":["child","teenager"]},
  {"id":"k16","title":"Leaf Treasure Hunt","desc":"Go for a walk and collect five different leaves. Compare shapes, colours, and sizes. Take them home and make a tiny nature museum.","cat":"outdoor","mins":60,"spend":0,"effort":1,"who":"sp","where":"out","light":"day","reach":0,"kit":["Small bag or basket","Magnifying glass (optional)","Paper and tape"],"tip":"Toddlers love carrying their own basket. Let them choose the 'best' leaf for each category.","season":"","ages":["toddler","child"]},
  {"id":"k17","title":"Bus Stop Adventure","desc":"Let your child choose a random bus stop or train stop. Get off and explore whatever park, café, or street you find nearby.","cat":"outdoor","mins":240,"spend":1,"effort":1,"who":"sp","where":"out","light":"day","reach":1,"kit":["Bus pass or tickets","Snacks","Water bottle","Small toy"],"tip":"Let the child press the stop button. That alone can make the trip feel magical.","season":"","ages":["toddler","child"]},
  {"id":"k18","title":"Chalk Street Gallery","desc":"Take pavement chalk outside and create drawings together. Invite passers-by to add their own doodle to the artwork.","cat":"creative","mins":60,"spend":1,"effort":1,"who":"pg","where":"out","light":"day","reach":0,"kit":["Pavement chalk","Camera for photos"],"tip":"Toddlers love scribbling huge circles. Photograph the artwork before rain washes it away.","season":"","ages":["toddler","child"]},
  {"id":"k19","title":"Colour Hunt Walk","desc":"Go for a walk and try to find five red things, five blue things, and five yellow things in your neighbourhood.","cat":"outdoor","mins":60,"spend":0,"effort":1,"who":"sp","where":"out","light":"day","reach":0,"kit":["Phone camera (optional)","Small bag"],"tip":"For toddlers, just finding one of each colour is enough. Take photos and review them later.","season":"","ages":["toddler","child"]},
  {"id":"k20","title":"Tiny Fairy House Builders","desc":"Use sticks, moss, bark, and stones to build a tiny fairy or bug house in the woods or garden.","cat":"outdoor","mins":60,"spend":0,"effort":1,"who":"sp","where":"out","light":"day","reach":0,"kit":["Sticks","Leaves","Small stones","Imagination"],"tip":"Toddlers enjoy placing the 'door'. You can revisit later to see if the fairies moved in.","season":"","ages":["toddler","child"]},
  {"id":"k21","title":"Toy Adventure Photographer","desc":"Bring a small toy on an outing and take photos of it doing adventures like climbing trees or riding slides.","cat":"creative","mins":60,"spend":0,"effort":1,"who":"sp","where":"any","light":"day","reach":0,"kit":["Small toy figure","Phone or camera"],"tip":"This works great with dinosaurs or teddy bears. Kids love seeing the photos later.","season":"","ages":["toddler","child"]},
  {"id":"k22","title":"Biggest Tree Picnic","desc":"Find the biggest tree you can in a park and have a snack underneath it. Talk about how old it might be.","cat":"outdoor","mins":60,"spend":1,"effort":1,"who":"sp","where":"out","light":"day","reach":0,"kit":["Picnic snack","Blanket","Water"],"tip":"Let your child try to hug the tree trunk to see if their arms fit around it.","season":"w","ages":["toddler","child"]},
  {"id":"k23","title":"Sound Safari","desc":"Sit somewhere quiet and count how many different sounds you can hear — birds, cars, wind, footsteps.","cat":"wellness","mins":60,"spend":0,"effort":1,"who":"sp","where":"out","light":"day","reach":0,"kit":["Nothing needed"],"tip":"Turn it into a guessing game: 'What animal made that sound?'","season":"","ages":["toddler","child"]},
  {"id":"k24","title":"Playground Explorer","desc":"Visit a playground you've never been to before and try every single piece of equipment.","cat":"outdoor","mins":60,"spend":0,"effort":1,"who":"sp","where":"out","light":"day","reach":1,"kit":["Snacks","Water bottle"],"tip":"Searching for new playgrounds can turn into a mini adventure series.","season":"","ages":["toddler","child"]},
  {"id":"k25","title":"Bug Safari","desc":"Look under logs and leaves to find insects and bugs.","cat":"outdoor","mins":60,"spend":0,"effort":1,"who":"sp","where":"out","light":"day","reach":0,"kit":["Magnifying glass"],"tip":"Turn it into a counting game.","season":"w","ages":["toddler","child"]},
  {"id":"k26","title":"Toy Picnic","desc":"Bring a teddy or toy and have a tiny picnic together.","cat":"social","mins":60,"spend":1,"effort":1,"who":"pg","where":"any","light":"day","reach":0,"kit":["Blanket","Snack"],"tip":"Let the toy 'eat' too.","season":"","ages":["toddler"]},
  {"id":"k27","title":"Bubble Chase","desc":"Blow bubbles and run around popping them.","cat":"social","mins":60,"spend":1,"effort":1,"who":"sp","where":"out","light":"day","reach":0,"kit":["Bubble wand"],"tip":"Windy days make it better.","season":"","ages":["toddler"]},
  {"id":"k28","title":"Mini Construction Site","desc":"Use sticks, dirt, and stones to build tiny roads and buildings.","cat":"social","mins":60,"spend":0,"effort":1,"who":"sp","where":"out","light":"day","reach":0,"kit":["Toy diggers optional"],"tip":"Bring toy vehicles.","season":"","ages":["toddler","child"]},
  {"id":"k29","title":"Cloud Watching","desc":"Lie down and look for shapes in the clouds.","cat":"wellness","mins":60,"spend":0,"effort":1,"who":"sp","where":"out","light":"day","reach":0,"kit":["Blanket"],"tip":"Take photos of funny shapes.","season":"w","ages":["toddler","child"]},
  {"id":"k30","title":"Nature Bracelet","desc":"Wrap tape around a wrist sticky-side out and attach leaves and petals.","cat":"creative","mins":60,"spend":0,"effort":1,"who":"sp","where":"out","light":"day","reach":0,"kit":["Tape"],"tip":"Masking tape works best.","season":"","ages":["child"]},
  {"id":"k31","title":"Library Story Time","desc":"Visit the library and pick three random picture books.","cat":"creative","mins":60,"spend":0,"effort":1,"who":"sp","where":"in","light":"day","reach":0,"kit":[],"tip":"Let the child choose based on cover.","season":"","ages":["toddler","child"]},
  {"id":"k32","title":"Theme Park Day Out","desc":"Pick a theme park and go all in. Rides, ice cream, stuffed toy from the arcade. The full works.","cat":"outdoor","mins":600,"spend":3,"effort":1,"who":"pg","where":"out","light":"day","reach":2,"kit":["Comfortable shoes","Waterproofs","Cash for extras","Portable charger"],"tip":"Book online for cheaper tickets. Arrive at opening for shorter queues. Pack snacks — park food is pricey. Alton Towers, Thorpe Park, and Legoland are all brilliant.","season":"","ages":["child","teenager"]},
  {"id":"k33","title":"Build-A-Bear & Lunch","desc":"Visit Build-A-Bear and let your child design their own stuffed animal. Follow it with lunch at their favourite restaurant.","cat":"creative","mins":240,"spend":3,"effort":1,"who":"sp","where":"in","light":"day","reach":1,"kit":["Wallet","Patience","Enthusiasm for naming ceremonies"],"tip":"The naming ceremony at the end is the highlight. Budget around £25-40 per bear. Let them choose everything — even the outfit.","season":"","ages":["toddler","child"]},
  {"id":"k34","title":"Sea Life Centre & Chippy Tea","desc":"Visit the nearest aquarium or Sea Life Centre. Watch the feeding time. Fish and chips on the way home.","cat":"outdoor","mins":600,"spend":3,"effort":1,"who":"sp","where":"in","light":"day","reach":2,"kit":["Camera","Snacks","Change of clothes for toddlers"],"tip":"Book online — it's always cheaper. Feeding times and talks are the highlight. The gift shop is unavoidable — set a budget beforehand.","season":"","ages":["toddler","child"]},
  {"id":"k35","title":"Family Glamping Night","desc":"Book a family bell tent or safari tent somewhere with animals and outdoor space. Campfire, stars, adventure.","cat":"outdoor","mins":2880,"spend":3,"effort":1,"who":"pg","where":"out","light":"any","reach":2,"kit":["Warm pyjamas","Wellies","Torches","Marshmallows","Board games"],"tip":"Feather Down Farms and family glamping sites often have animals to feed, dens to build, and fire pits. Book one with proper beds — everyone sleeps better.","season":"w","ages":["toddler","child","teenager"]},
  {"id":"k36","title":"West End Kids' Show","desc":"Book tickets to a kids' show in the West End or a local theatre. Dress up. Make it an event.","cat":"social","mins":600,"spend":3,"effort":1,"who":"sp","where":"in","light":"any","reach":2,"kit":["Smart-ish clothes","Pre-booked tickets","Snacks for the interval"],"tip":"Matilda, The Lion King, and Wicked are all spectacular for kids. Book matinee performances. Arrive early to soak up the atmosphere. TodayTix often has deals.","season":"","ages":["child","teenager"]},
  {"id":"k37","title":"Rainy Day Fort Building","desc":"Gather every cushion, blanket, and pillow in the house. Build the ultimate indoor fort. Read stories inside it by torchlight.","cat":"creative","mins":240,"spend":0,"effort":1,"who":"pg","where":"in","light":"any","reach":0,"kit":["Cushions and pillows","Blankets and sheets","Pegs or clips","Torches","Snacks","Books"],"tip":"Use dining chairs as the frame. Fairy lights inside make it magical. Let the kids design it themselves. Hot chocolate served inside the fort is mandatory.","season":"","ages":["toddler","child"]},
  {"id":"k38","title":"Mini Beast Safari","desc":"Grab a magnifying glass and a spotter sheet. Explore the garden or park looking for woodlice, spiders, beetles, and worms. Keep a tally.","cat":"outdoor","mins":60,"spend":0,"effort":1,"who":"sp","where":"out","light":"day","reach":0,"kit":["Magnifying glass","Spotter sheet","Pencil","Collection pot (temporary!)","Wellies"],"tip":"Under logs and stones is where the action is. Always put logs back gently. Rainy days are best for worms and slugs. Count species like a real scientist.","season":"w","ages":["child"]},
  {"id":"k39","title":"Kitchen Science Experiments","desc":"Do three science experiments using stuff from the kitchen — vinegar volcanoes, invisible ink with lemon juice, colour-changing milk.","cat":"creative","mins":240,"spend":1,"effort":1,"who":"pg","where":"in","light":"any","reach":0,"kit":["Baking soda","Vinegar","Food colouring","Washing-up liquid","Milk","Lemon","Paper","Trays for mess"],"tip":"Cover the table first — it will get messy. The baking soda and vinegar volcano never gets old. Older kids love the elephant toothpaste experiment.","season":"","ages":["child","teenager"]},
  {"id":"k40","title":"Letterboxing Trail","desc":"Find a letterboxing trail near you. Follow the clues, find the hidden stamps, collect them in your book.","cat":"outdoor","mins":240,"spend":0,"effort":1,"who":"pg","where":"out","light":"day","reach":2,"kit":["Notebook","Ink pad","Comfortable shoes","Clue sheet","Pencil"],"tip":"Dartmoor is the spiritual home of letterboxing but they're everywhere. It's like geocaching but analogue. The hunt is the adventure.","season":"","ages":["child","teenager"]},
  {"id":"k41","title":"Obstacle Course Challenge","desc":"Set up a garden obstacle course — crawl under chairs, jump over buckets, balance on planks, throw balls at targets. Time each run.","cat":"outdoor","mins":240,"spend":0,"effort":1,"who":"pg","where":"out","light":"day","reach":0,"kit":["Garden chairs","Buckets","Planks or ropes","Balls","Stopwatch","Prizes"],"tip":"Let the kids help design the course — they'll make it harder than you ever would. Adults must attempt it too. Muddy sections add to the fun.","season":"w","ages":["child","teenager"]},
  {"id":"k42","title":"Sunrise Breakfast Picnic","desc":"Wake the kids before dawn. Drive somewhere beautiful. Watch the sunrise together while eating pastries and hot chocolate.","cat":"outdoor","mins":60,"spend":1,"effort":1,"who":"pg","where":"out","light":"any","reach":1,"kit":["Pastries or croissants","Hot chocolate in flasks","Blankets","Warm clothes","Camera"],"tip":"The novelty of being up before dawn makes kids feel like adventurers. Choose a high viewpoint. Wrap them in blankets. They'll remember it forever.","season":"","ages":["child","teenager"]},
  {"id":"k43","title":"Map Your Neighbourhood","desc":"Give kids paper and pens. Walk around the block and let them draw a map of everything they see — post boxes, trees, cats, funny signs.","cat":"creative","mins":60,"spend":0,"effort":1,"who":"sp","where":"out","light":"day","reach":0,"kit":["Paper","Coloured pens","Clipboard","Walking shoes"],"tip":"Let them decide what's important enough to go on the map. Add a legend with symbols. Frame the finished map — it's folk art.","season":"","ages":["child"]},
  {"id":"k44","title":"Mud Kitchen Cooking","desc":"Set up a mud kitchen in the garden with old pots, spoons, and containers. Let kids 'cook' mud pies, soups, and cakes.","cat":"outdoor","mins":240,"spend":0,"effort":1,"who":"sp","where":"out","light":"day","reach":0,"kit":["Old pots and pans","Wooden spoons","Containers","Water","Flowers and leaves for decoration","Old clothes"],"tip":"Add water to make it properly messy. Flower petals as garnish. Accept that everything will need hosing down afterwards. Pure joy.","season":"","ages":["toddler","child"]},
  {"id":"k45","title":"Nighttime Garden Safari","desc":"After dark, take torches into the garden and look for moths, slugs, hedgehogs, and spiders' webs glistening with dew.","cat":"outdoor","mins":60,"spend":0,"effort":1,"who":"pg","where":"out","light":"night","reach":0,"kit":["Torches","Warm layers","Bug identification app","Notebook"],"tip":"Leave a white sheet with a light on it for 30 minutes to attract moths. Check under plant pots for slugs. Hedgehogs come out around 9pm in summer.","season":"w","ages":["child","teenager"]},
  {"id":"k46","title":"Bake & Deliver","desc":"Bake biscuits or cupcakes together. Decorate them. Then deliver them to neighbours, friends, or family as surprise gifts.","cat":"food","mins":240,"spend":1,"effort":1,"who":"pg","where":"in","light":"any","reach":0,"kit":["Baking ingredients","Decorating supplies","Gift bags or boxes","Aprons"],"tip":"Simple sugar biscuits are best for decorating. Let toddlers do the sprinkles. The delivery walk turns it into a proper adventure. Neighbours love it.","season":"","ages":["toddler","child"]},
  {"id":"k47","title":"River Stone Skimming","desc":"Find a calm stretch of river or lake. Collect flat stones. See who can get the most skips. Family championship.","cat":"outdoor","mins":60,"spend":0,"effort":1,"who":"pg","where":"out","light":"day","reach":1,"kit":["Collection of flat stones","Towel","Snacks"],"tip":"Flat, smooth stones about the size of your palm work best. Side-arm throw, low angle. Kids pick it up quickly. The world record is 88 skips.","season":"w","ages":["child","teenager"]}
],
sheffield:[
  {"id":"shef-1","title":"Peveril Castle Exploration","desc":"Explore the ruins of Peveril Castle perched above Castleton. Built by William Peverel after the Norman Conquest, the views over the Hope Valley are spectacular.","cat":"outdoor","mins":240,"spend":1,"effort":1,"who":"sp","where":"out","light":"day","reach":1,"kit":["Comfortable shoes","Camera","Layers — it's windy up top","Water bottle","Packed lunch for the village green after"],"tip":"Combine with a walk through Cave Dale for a dramatic approach. English Heritage members get free entry. Castleton has great cafés for after.","season":""},
  {"id":"shef-2","title":"Bolsover Castle Day Out","desc":"Visit the stunning Bolsover Castle with its bizarre indoor riding school and ornate Little Castle. A proper hidden gem on the edge of the Peak District.","cat":"urban","mins":240,"spend":1,"effort":1,"who":"sp","where":"any","light":"day","reach":1,"kit":["Camera","Comfortable shoes","Picnic supplies"],"tip":"The wall paintings inside the Little Castle are extraordinary. Check for jousting event days. The views from the ramparts stretch for miles.","season":""},
  {"id":"shef-3","title":"Haddon Hall Visit","desc":"Step into one of England's best-preserved medieval manor houses. Haddon Hall near Bakewell is hauntingly beautiful with its Tudor gardens and stone courtyards.","cat":"urban","mins":240,"spend":2,"effort":1,"who":"sp","where":"any","light":"day","reach":1,"kit":["Camera","Comfortable shoes","Cash for the gift shop"],"tip":"It's been used as a filming location for Pride & Prejudice and Jane Eyre. The Long Gallery is breathtaking. Visit in June when the roses are out.","season":""},
  {"id":"shef-4","title":"Wild Swim at Slippery Stones","desc":"Hike up the Upper Derwent Valley to Slippery Stones — a series of natural pools and cascades perfect for a wild dip. Remote, beautiful, and properly refreshing.","cat":"outdoor","mins":600,"spend":0,"effort":2,"who":"sp","where":"out","light":"day","reach":1,"kit":["Swimsuit","Towel","Water shoes — the rocks are slippery","Warm layers for after","Thermos with hot drink","Packed lunch","Dry bag"],"tip":"Park at Fairholmes car park and walk up. The water is always cold — acclimatise slowly. Go on a weekday to avoid crowds. Never swim alone.","season":"w"},
  {"id":"shef-5","title":"Padley Gorge Plunge Pool","desc":"Scramble through the ancient oak woodland of Padley Gorge to find the plunge pools along Burbage Brook. A magical spot that feels a million miles from Sheffield.","cat":"outdoor","mins":240,"spend":0,"effort":2,"who":"sp","where":"out","light":"day","reach":1,"kit":["Swimsuit","Quick-dry towel","Sturdy shoes — it's rocky","Warm clothes for after","Snacks","Waterproof bag for phone"],"tip":"Park at Grindleford station and walk through the gorge. The pools are shallow but freezing — perfect for a quick dip. The woodland is ancient and stunning in autumn.","season":"w"},
  {"id":"shef-6","title":"Hathersage Outdoor Pool","desc":"Swim in the heated open-air pool in Hathersage village — one of England's few remaining lidos, set against a backdrop of Peak District hills.","cat":"outdoor","mins":240,"spend":1,"effort":1,"who":"pg","where":"out","light":"day","reach":1,"kit":["Swimsuit","Towel","Goggles","Picnic for the poolside lawn","Sun cream"],"tip":"Open May to September. Go early on a sunny day before it gets busy. The water is heated but still bracing. The poolside café does great bacon sandwiches.","season":"w"},
  {"id":"shef-7","title":"Stanage Edge Scramble","desc":"Walk the full length of Stanage Edge — Sheffield's iconic gritstone escarpment. Three miles of dramatic cliffs with views that never get old.","cat":"outdoor","mins":240,"spend":0,"effort":2,"who":"sp","where":"out","light":"day","reach":1,"kit":["Hiking boots","Windproof jacket","Water and snacks","Map or phone GPS","Camera"],"tip":"Park at the Hooks Car car park or Dennis Knoll. Walk north for the best light in the afternoon. Watch the climbers on the edge. The millstones scattered along the base are fascinating.","season":""},
  {"id":"shef-8","title":"Kinder Scout Summit","desc":"Bag the Peak District's highest point. Start from Edale and climb via Grindsbrook Clough for a proper scramble to the top of the Dark Peak.","cat":"outdoor","mins":600,"spend":0,"effort":3,"who":"sp","where":"out","light":"day","reach":1,"kit":["Hiking boots","Waterproofs","Map & compass","Packed lunch","Water — at least 2 litres","Warm layers","Head torch (just in case)"],"tip":"The Grindsbrook route is the most dramatic. Navigation on the plateau can be tricky in mist — bring a compass. Visit Kinder Downfall if there's been rain. Historic ground — the Mass Trespass happened here in 1932.","season":""},
  {"id":"shef-9","title":"Bakewell Pudding Crawl","desc":"Head to Bakewell and try the original Bakewell Pudding from at least three different shops. Each claims to have the authentic recipe — you decide who wins.","cat":"food","mins":240,"spend":1,"effort":1,"who":"sp","where":"any","light":"day","reach":1,"kit":["Empty stomach","Cash — some shops are cash only","Notebook for scoring","Walking shoes for the town"],"tip":"The Old Original Bakewell Pudding Shop and Bloomers are the main rivals. It's a pudding, not a tart — important distinction. Cross the medieval bridge and walk along the river to aid digestion.","season":""},
  {"id":"shef-10","title":"Kelham Island Pub Crawl","desc":"Explore Sheffield's Kelham Island quarter — craft breweries, independent bars, and street food in converted industrial buildings.","cat":"food","mins":240,"spend":2,"effort":1,"who":"pg","where":"in","light":"night","reach":0,"kit":["Comfortable shoes","Cash for some venues","Empty stomach","Good company"],"tip":"Start at Kelham Island Tavern (CAMRA pub of the year multiple times). Hit True North and the Fat Cat. The street food options are brilliant. Go on a Saturday afternoon.","season":""},
  {"id":"shef-11","title":"Surprise View Sunrise","desc":"Drive up to Surprise View above Hathersage for dawn. Watch the Hope Valley fill with mist as the sun comes up over the edges.","cat":"outdoor","mins":60,"spend":0,"effort":1,"who":"s","where":"out","light":"any","reach":1,"kit":["Warm layers — it's freezing before dawn","Thermos with coffee","Camera or phone","Blanket to sit on","Head torch for the walk from the car"],"tip":"Check sunrise time and arrive 30 mins early. Best in autumn when temperature inversions create sea-of-cloud effects. The layby fills up fast on clear mornings.","season":""},
  {"id":"shef-12","title":"Chatsworth House & Gardens","desc":"Spend a day at Chatsworth — the jewel of the Peak District. Explore the house, gardens, farmyard, and the epic adventure playground.","cat":"urban","mins":600,"spend":2,"effort":1,"who":"pg","where":"any","light":"day","reach":1,"kit":["Comfortable shoes","Camera","Packed lunch or money for the café","Layers for the garden"],"tip":"The garden alone is worth the visit — the Cascade and the Emperor Fountain are incredible. Check for special exhibitions. The farm shop is dangerous for your wallet.","season":""},
  {"id":"shef-13","title":"Rivelin Valley Nature Walk","desc":"Follow the Rivelin Valley trail through Sheffield's green corridor. Old mill ponds, stepping stones, and woodland right on the city's doorstep.","cat":"outdoor","mins":240,"spend":0,"effort":1,"who":"sp","where":"out","light":"day","reach":0,"kit":["Walking shoes","Waterproof jacket","Camera","Snacks","Dog (optional)"],"tip":"Start from Rivelin Valley Road and follow the river upstream. The old mill ruins are fascinating. It connects to the Wyming Brook trail for a longer walk. Beautiful in spring with bluebells.","season":""},
  {"id":"shef-14","title":"Mam Tor Ridge Walk","desc":"Walk the Great Ridge from Mam Tor to Lose Hill. One of the finest ridge walks in England with views across both the Dark and White Peak.","cat":"outdoor","mins":240,"spend":0,"effort":2,"who":"sp","where":"out","light":"day","reach":1,"kit":["Hiking boots","Windproof jacket — it's exposed","Water and snacks","Camera","Map"],"tip":"Start from the Mam Nick car park. Walk east along the ridge to Lose Hill, then drop down to Castleton for a pub lunch. The wind on the ridge can be fierce — dress accordingly.","season":""},
  {"id":"shef-15","title":"Sheffield Street Art Tour","desc":"Explore Sheffield's ever-changing street art scene. From the murals of Division Street to the hidden pieces in the alleys of Devonshire Quarter.","cat":"urban","mins":240,"spend":0,"effort":1,"who":"sp","where":"any","light":"day","reach":0,"kit":["Camera or phone","Comfortable shoes","Coffee for the walk"],"tip":"The city centre has loads — check behind the Leadmill and around Sidney Street. Kid Acne and Phlegm are local legends. It changes constantly so there's always something new.","season":""},
  {"id":"shef-16","title":"Ladybower Reservoir Circuit","desc":"Walk or cycle the full circuit of Ladybower Reservoir in the Upper Derwent Valley. When water levels drop, the ruins of drowned villages emerge.","cat":"outdoor","mins":600,"spend":0,"effort":2,"who":"sp","where":"out","light":"day","reach":1,"kit":["Bike or hiking boots","Water and packed lunch","Camera","Waterproofs","Snacks"],"tip":"The Derwent Dam was used by 617 Squadron to practise for the Dambusters raid. The full loop is about 8 miles on foot. Visit after dry spells to see the old village foundations emerge from the water.","season":""},
  {"id":"shef-17","title":"Abbeydale Industrial Hamlet","desc":"Step back in time at this preserved 18th-century scythe-making works on the River Sheaf. Sheffield's industrial heritage brought to life.","cat":"urban","mins":60,"spend":0,"effort":1,"who":"sp","where":"in","light":"day","reach":0,"kit":["Camera","Comfortable shoes"],"tip":"Free entry. Check for working days when they fire up the water wheel and forge. The site is a Scheduled Ancient Monument. Combine with a walk along the Sheaf Valley.","season":""},
  {"id":"shef-18","title":"Peak District Pub Walk","desc":"Pick a classic Peak District circular walk that starts and ends at a country pub. Walk for three hours, eat a roast, walk home.","cat":"outdoor","mins":600,"spend":2,"effort":2,"who":"pg","where":"out","light":"day","reach":1,"kit":["Hiking boots","Waterproofs","Map","Cash for the pub","Appetite"],"tip":"The Scotsman's Pack in Hathersage, the Plough at Hathersage Booths, or the Cheshire Cheese at Hope are all brilliant starts. Book a table for busy Sundays. A pint of local ale after a walk is unbeatable.","season":""},
  {"id":"shef-19","title":"Forge Dam & Porter Brook Walk","desc":"Start at Endcliffe Park and walk upstream through Bingham Park and Whiteley Woods to Forge Dam. Waterfalls, woodland, and a café at the top.","cat":"outdoor","mins":60,"spend":0,"effort":1,"who":"sp","where":"out","light":"day","reach":0,"kit":["Walking shoes","Light layers","Cash for café at Forge Dam"],"tip":"A Sheffield classic. Follow Porter Brook all the way up. The café at Forge Dam does a great brew. In autumn the colours are extraordinary. Keep going past the dam for wilder paths.","season":""},
  {"id":"shef-20","title":"Castleton Caves Adventure","desc":"Explore the show caves of Castleton — Peak Cavern (the Devil's Arse), Speedwell, Treak Cliff, and Blue John. Go underground and discover another world.","cat":"outdoor","mins":600,"spend":2,"effort":1,"who":"pg","where":"in","light":"day","reach":1,"kit":["Warm layers — caves are cold","Comfortable shoes","Camera (no flash)","Cash for tickets"],"tip":"Speedwell involves a boat ride through a flooded mine tunnel — incredible. Treak Cliff has the best Blue John stone. Peak Cavern has the most dramatic entrance. Do at least two for comparison.","season":""},
  {"id":"shef-21","title":"Curbar Edge Sunset","desc":"Walk up to Curbar Edge for golden hour. The gritstone glows orange as the sun sets over the Derwent Valley. Bring a flask and stay until dark.","cat":"outdoor","mins":60,"spend":0,"effort":1,"who":"sp","where":"out","light":"any","reach":1,"kit":["Warm layers","Flask with hot drink","Camera","Blanket to sit on","Head torch for the walk down"],"tip":"Park at Curbar Gap. Walk south along the edge for the best viewpoints. Sunset in autumn is spectacular. Watch the climbers on the buttresses as the light fades.","season":""},
  {"id":"shef-22","title":"Ecclesall Woods Foraging","desc":"Join a seasonal foraging walk in Ecclesall Woods — one of Sheffield's ancient woodlands. Wild garlic in spring, blackberries in autumn, mushrooms if you know your stuff.","cat":"food","mins":240,"spend":0,"effort":1,"who":"sp","where":"out","light":"day","reach":0,"kit":["Basket or bag","Foraging guide","Comfortable shoes","Knife","Recipe ideas"],"tip":"Wild garlic carpets the woods in April — you can smell it before you see it. Only pick what you can identify with certainty. Ecclesall Woods Trust runs guided walks.","season":""},
  {"id":"shef-23","title":"Whirlow Hall Farm Visit","desc":"Spend a morning at Whirlow Hall Farm on the edge of the city. Feed the animals, walk the fields, buy from the farm shop. A proper farm on Sheffield's doorstep.","cat":"outdoor","mins":240,"spend":1,"effort":1,"who":"pg","where":"out","light":"day","reach":0,"kit":["Wellies","Old clothes","Camera","Cash for the farm shop"],"tip":"Check their events calendar for lambing weekends and harvest days. The farm shop sourdough is excellent. Combine with a walk up to Whirlow Brook Park.","season":""},
  {"id":"shef-24","title":"Kelham Island Museum","desc":"Explore Sheffield's industrial heritage at Kelham Island Museum. See the mighty River Don Engine in steam — the most powerful working steam engine in Europe.","cat":"urban","mins":240,"spend":1,"effort":1,"who":"sp","where":"in","light":"day","reach":0,"kit":["Comfortable shoes","Camera"],"tip":"The River Don Engine runs at set times — check before you go. The 'Made in Sheffield' exhibition tells the city's story brilliantly. Combine with a Kelham Island pub crawl afterwards.","season":""},
  {"id":"shef-25","title":"Graves Park to Beauchief Abbey","desc":"Walk from Graves Park through the woods to the ruins of Beauchief Abbey. A peaceful medieval ruin hidden on Sheffield's southern fringe.","cat":"outdoor","mins":240,"spend":0,"effort":1,"who":"sp","where":"out","light":"day","reach":0,"kit":["Walking shoes","Camera","Packed lunch","Dog (optional)"],"tip":"Graves Park is Sheffield's largest park. The walk to the abbey is gentle and wooded. The abbey ruins are atmospheric and usually deserted. Stop at the Beauchief for a pint on the way back.","season":""},
  {"id":"shef-26","title":"Rother Valley Country Park","desc":"Cycle, kayak, or just walk around Rother Valley Country Park. Watersports, nature trails, and a cable wakeboard. Something for everyone.","cat":"outdoor","mins":600,"spend":1,"effort":1,"who":"pg","where":"out","light":"day","reach":1,"kit":["Bike or walking shoes","Swimsuit (for watersports)","Towel","Packed lunch","Sun cream"],"tip":"The cable wakeboarding is brilliant for beginners. Bike hire is available. The nature reserve at the southern end is great for birdwatching. Go on a weekday to avoid crowds.","season":""},
  {"id":"shef-27","title":"Totley Tunnel & Padley Chapel","desc":"Walk from Totley station through the fields to the mouth of Totley Tunnel — the longest mainline rail tunnel in the UK. Continue to the medieval Padley Chapel.","cat":"outdoor","mins":240,"spend":0,"effort":1,"who":"sp","where":"out","light":"day","reach":0,"kit":["Walking shoes","Waterproof","Camera","Flask"],"tip":"Stand at the tunnel mouth and feel the rush of air as trains pass. Padley Chapel is a hidden gem with a moving history. The walk through Padley Gorge is stunning.","season":""},
  {"id":"shef-28","title":"Sheffield Round Walk Section","desc":"Tackle a section of the Sheffield Round Walk — a 15-mile circular route hitting the city's seven hills. Pick any quarter and discover views you never knew existed.","cat":"outdoor","mins":240,"spend":0,"effort":2,"who":"sp","where":"out","light":"day","reach":0,"kit":["Hiking boots","Map or phone GPS","Water and snacks","Waterproof","Camera"],"tip":"The full route is 15 miles but splits into manageable sections. The stretch from Norfolk Park to Meersbrook gives incredible city views. Well-signed with yellow arrows.","season":""},
  {"id":"shef-29","title":"Botanical Gardens & Weston Park","desc":"Spend a morning wandering Sheffield's Botanical Gardens — Victorian glass pavilions, themed gardens, and a bear pit. Walk across to Weston Park Museum afterwards.","cat":"urban","mins":240,"spend":0,"effort":1,"who":"sp","where":"any","light":"day","reach":0,"kit":["Camera","Book for the bench","Coffee from the café"],"tip":"The glass pavilions house tropical and desert plants. The bear pit is empty now but fascinating. Weston Park Museum is free and excellent. Perfect for a rainy day.","season":""},
  {"id":"shef-30","title":"Win Hill Pike","desc":"Bag Win Hill — the Peak District's best viewpoint-for-effort ratio. Short, sharp climb rewarded with 360° views over Ladybower, the Great Ridge, and Kinder.","cat":"outdoor","mins":240,"spend":0,"effort":2,"who":"sp","where":"out","light":"day","reach":1,"kit":["Hiking boots","Windproof jacket","Water and snacks","Camera","Map"],"tip":"Start from Yorkshire Bridge car park for the shortest route up. The summit trig point is one of the best photo spots in the Peak District. Combine with a pint at the Ladybower Inn.","season":""}
]
};
